CREATE TABLE `local_sessions` (
	`id` int AUTO_INCREMENT NOT NULL,
	`userId` int NOT NULL,
	`token` varchar(255) NOT NULL,
	`expiresAt` timestamp NOT NULL,
	`createdAt` timestamp NOT NULL DEFAULT (now()),
	CONSTRAINT `local_sessions_id` PRIMARY KEY(`id`),
	CONSTRAINT `local_sessions_token_unique` UNIQUE(`token`)
);
ALTER TABLE `users` MODIFY COLUMN `openId` varchar(64);
ALTER TABLE `users` MODIFY COLUMN `loginMethod` varchar(64) DEFAULT 'local';
ALTER TABLE `users` ADD `username` varchar(100);
ALTER TABLE `users` ADD `passwordHash` text;
ALTER TABLE `users` ADD `emailVerified` boolean DEFAULT false NOT NULL;
ALTER TABLE `users` ADD CONSTRAINT `users_username_unique` UNIQUE(`username`);
ALTER TABLE `users` ADD CONSTRAINT `users_email_unique` UNIQUE(`email`);

